#include<stdio.h>
int sandhya(int n)
{
    int i;
    if(n<=1)
        return 0;
    for(i=2;i<=n/2;i++){
        if(n%i==0)
            return 0;
    }
    return 1;
}
int main()
{
    int n;
    printf("Enter a number:");
    scanf("%d",&n);
    if(sandhya(n))
        printf("%d is a prime number",n);
    else 
        printf("%d is not a prime number",n);
    return 0;
}

#include<stdio.h>
#include<string.h>
int ispalindrome(char str[])
{
    int i,len;
    len=strlen(str);
    for(i=0;i<len/2;i++){
        if(str[i]!=str[len-i-1]){
            return 0;
        }
    }
    return 1;
}
int main()
{
    char str[100];
    printf("Enter a string:");
    scanf("%s", str);
    if(ispalindrome(str))
        printf("%s is a palindrome.\n",str);
    else
        printf("%s is not a palindrome.\n",str);
    return 0;
}

