#include<stdio.h>
int sum(int n){
    if(n==0)
        return 0;
    else
        return n+sum(n-1);
}
int main(){
    int n,result;
    printf("Enter a positive integer: ");
    scanf("%d",&n);
    result=sum(n);
    printf("sum of natural numbers=%d",result);
    return 0;
}

#include<stdio.h>
int factorial(int n)
{
    if(n==0)
    {
        return 1;
    }
    return n*factorial(n-1);
}
int main()
{
    int n;
    printf("Enter a number: ");
    scanf("%d",&n);
    if(n<0)
        printf("Factorial is not defined for negative numbers.\n");
    else
        printf("Factorial of %d=%d\n",n,factorial(n));
    return 0;
}

#include<stdio.h>
#include<math.h>
int isarmstrong(int i)
{
    int num,remainder,sum,digit,j,s;
    s=i;

    digit=0;
    sum=0;
    num=s;
    for(j=s;j!=0;j=j/10)
    {
        digit++;
    }

    while(s!=0)
    {
        remainder=s%10;
        sum=sum+pow(remainder,digit);
        s=s/10;
    }
    if(sum==num)
        return 1;
    else
        return 0;
}
int main()
{
    int start,end,i;
    printf("Enter the starting range: ");
    scanf("%d",&start);
    printf("Enter a ending number: ");
    scanf("%d",&end);
    printf("Armstrong numbers between %d and %d are:\n",start,end);
    for(i=start;i<=end;i++)
    {
        if(isarmstrong(i))
            printf("%d\n",i);
    }
    return 0;
}

#include<stdio.h>
void diamond(int n)
{
    int i,j;
    for(i=1;i<=n;i++)
    {
        for(j=1;j<=n-i;j++)
            printf(" ");
        for(j=1;j<=i;j++)
            printf("*");
        for(j=1;j<i;j++)
            printf("*");
        printf("\n");
    }
    for(i=1;i<=n-1;i++)
    {
        for(j=1;j<=i;j++)
            printf(" ");
        for(j=1;j<=n-i;j++)
            printf("*");
        for(j=1;j<n-i;j++)
            printf("*");
        printf("\n");
    }
}
int main()
{
    int n;
    printf("Enter number of rows: ");
    scanf("%d",&n);
    diamond(n);
    return 0;
}

#include<stdio.h>
int fibonacci(int n){
    if(n==0)
        return 0;
    else if(n==1)
        return 1;
    else
        return fibonacci(n-1)+fibonacci(n-2);
}
int main(){
    int n,i;
    printf("Enter a number of terms: ");
    scanf("%d",&n);
    printf("Fibonacci series: ");
    for(i=0;i<n;i++)
        printf("%d",fibonacci(i));
    return 0;
}

#include<stdio.h>
#include<string.h>
int main(){
    int n,i,j;
    char str[20][50],temp[50];
    printf("Enter the number of strings: ");
    scanf("%d",&n);
    printf("Enter the strings:\n");
    for(i=0;i<n;i++){
        scanf("%s",str[i]);
    }
    for(i=0;i<n-1;i++){
        for(j=i+1;j<n;j++){
            if(strcmp(str[i],str[j])>0){
                strcpy(temp,str[i]);
                strcpy(str[i],str[j]);
                strcpy(str[j],temp);
            }
        }
    }
    printf("\nStrings in Lexicographical Order:\n");
    for(i=0;i<n;i++){
        printf("%s\n",str[i]);
    }
    return 0;
}

